import React from 'react'
import { clone, map, isArray, omit } from 'lodash'
import { Customary } from './Customary';

const mapWithStack = {
  column: 'stacked_column',
  area: 'stacked_line',
  bar: 'stacked_bar',
}
const GraphTypeDropdown = ({
  handleChartChange,
  graphTypeVal,
  graphTypeObj,
  graphData,
  group_list: groupList,
}) => {
  const dateTypes = [
    // session analytics
    'session_period_day',
    'session_period',
    'session_date_week',
    'session_date_month',
    'session_period_hour',
    // event page
    'event_period',
    'event_period_day',
    'event_period_hour',
    'event_date_month',
    'event_date_week',
    // user analytics
    'user_period_hour',
    'user_period',
    'user_date_week',
    'user_date_month',
  ]
  let graphTypeObjCloned = clone(graphTypeObj)
  const newGrpByVal = groupList ? [...groupList] : []
  const pluckedGroupList = map(newGrpByVal, 'attribute')
  const isExcluded = pluckedGroupList.length === 1 ? dateTypes.includes(pluckedGroupList[0]) : dateTypes.includes(pluckedGroupList[0]) || dateTypes.includes(pluckedGroupList[1])
  if (isExcluded) graphTypeObjCloned = omit(graphTypeObjCloned, 'pie')
  const newGraphData = graphData && graphData['data']
  const series =
    newGraphData &&
    isArray(newGraphData['plot']['series']) &&
    newGraphData['plot']['series'].length &&
    newGraphData['plot']['series']
  let graphType = series && series[0]['type']
  const stackedType = series && series[0]['stacking']
  if (graphType && stackedType) graphType = mapWithStack[graphType]
  return (
    <Customary
      handleChange={handleChartChange}
      options={graphTypeObjCloned}
      id="graph_type_dropdown"
      placeholder="Select an chart"
      defaultValue={graphType || graphTypeVal}
      value={graphType || graphTypeVal}
      dropdownClassName="graph-type-dropdown"
      style={{ width: 50 }}
    />
  )
}

export default GraphTypeDropdown
