import React, { createRef, memo } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import {
  clone,
  each,
  isObject,
  findLastIndex,
  reject,
  isEmpty,
  map,
} from 'lodash'
import LoaderAdvanced from 'components/common/LoaderAdvanced';
import { handleValuesByName } from 'redux/actions/sessionStatistics'
import Wrapper from 'components/common/Customary/Wrapper'
import GraphTypeDropdown from 'components/common/Customary/GraphTypeDropdown'
import { graphTypeObj } from 'components/common/Customary/graphType'
import CategoryLevelDropdown from 'components/common/CategoryLevelDropdown'
import StatisticsGraph from 'components/common/StatisticsGraph'
import CustomExportGraphDropdown from 'Utils/helpers/CustomExportGraphDropdown'
import { insideLoader, findCategoryTitle } from 'Utils/helpers/commonUtils'
import { fetchPlanHatApi } from 'redux/actions/common'
import { setGroupList, setSeriesPlotOptions } from 'redux/actions/userList'
import useSessionAnalyticsAPI from 'components/features/sessions/SessionStatistics/hooks/useSessionAnalyticsAPI'
import { getTimezoneOffset } from 'Utils/DateConversion/dateConversionUtils';
import { useIsAppType } from 'hooks/useIsAppType';

export const getRestructedUTMData = (userFirstUtm = []) => {
  return userFirstUtm?.map(item => ({
    attribute: item,
    categoryTitle: "Initial landing UTM",
    display: item,
    json_field: [item],
    max_group_number: 50,
    table: "appuser",
    type: "json"
  }));
}

const chartRef = createRef()
const Statistics = (props) => {
  const dispatch = useDispatch();
  const { callGraphApi, callStatsBoxes } = useSessionAnalyticsAPI();
  const {
    groupingOptions,
    graphData,
    group_list = [],
    series_plot_options,
    selectedBox,
    graphLoader,
  } = props
  const groupListCopy = [ ...group_list ]
  const { bottomBarClassFlag } = useSelector((state) => state.commonReducer)
  const { parentType } = useSelector((state) => state.urlReducer)
  const { dateSegment, fetchProperty } = useSelector((state) => state.appFilter);
  const isWebSdk = useIsAppType('web');
  
  const graphTypeVal = series_plot_options?.key
  const userFirstUtm = fetchProperty?.user_first_utm?.data || [];
  const restructuredUTMData = getRestructedUTMData(userFirstUtm);
  if (groupingOptions && groupingOptions.groupby_dropdown && isWebSdk) {
    groupingOptions.groupby_dropdown['Initial landing UTM'] = restructuredUTMData;
  }
  const groupby_dropdown =
    groupingOptions && clone(groupingOptions.groupby_dropdown)
  const __handleValuesByName = (payload) => {
    if (parentType === 'usersAnalytics') dispatch(setGroupList(payload[groupListCopy]))
    else dispatch(handleValuesByName(payload))
  }
  const removeValue = (array, id) => reject(array, (item, index) =>
       index === id // or some complex logic
    )
  const delGrpByArr = async (_index) => {
    const groupListNew = removeValue(groupListCopy, _index)
    const payload = {
      dropName: 'group_list',
      data: [...groupListNew],
    }
    if (parentType === 'usersAnalytics') await dispatch(setGroupList([...groupListNew]))
    else await dispatch(handleValuesByName(payload))
    callGraphApi({ grpList: [...groupListNew] })
  }
  const handleChartChange = async (val) => {
    const payload = {
      dropName: 'series_plot_options',
      data: graphTypeObj[val],
    }
    if (parentType === 'usersAnalytics') await dispatch(setSeriesPlotOptions(graphTypeObj[val]))
    else await dispatch(handleValuesByName(payload))
    callGraphApi({ seriesPlotsOptions: graphTypeObj[val] })
    dispatch(
      fetchPlanHatApi({
        action: 'Graph type changed',
        info: {
          'Graph type': val,
          page: parentType,
        },
      })
    )
  }

  const handleGrpBy = async (
    selectedData,
    id,
    index,
    isKeyPress,
    operator,
    categorytitle,
    keyByCategory,
    isShowTopActivated,
    max_group_number,
    labels
  ) => {
    if (!labels?.length) labels = undefined
    if (!isShowTopActivated) max_group_number = 50
    const keyPressValue = isKeyPress && selectedData
    const value = keyPressValue || (keyByCategory || selectedData.item.props.value)
    let newGroupList; let payloadObj; let categorytitleCopy; let eventDisplay
    let newPData; const obj = {};
    const groupby_dropdown = groupingOptions?.groupby_dropdown
    await each(groupby_dropdown, (val) => {
      val.map((x) => {
        obj.values = {
          ...obj.values,
          [x.attribute]: x.table,
        }
      })
    })
    if (Object.keys(obj.values).indexOf(value) === -1) eventDisplay = 'User property'
    const isInitialLandingUTM = findCategoryTitle(value, groupby_dropdown) === 'Initial landing UTM'

    selectedData = isObject(selectedData) ? selectedData.key : selectedData
    if ( isInitialLandingUTM ){
      payloadObj = {
        attribute: 'user_first_utm',
        table: 'appuser',
        type: 'json',
        display: value,
        json_field: [value],
        max_group_number,
        labels,
      }
    } else if (!eventDisplay) {
      categorytitleCopy = categorytitle || selectedData?.item?.props?.categorytitle
      const indexOfValue = findLastIndex(groupby_dropdown[categorytitleCopy], { display: selectedData, })
      newPData = groupby_dropdown[categorytitleCopy][indexOfValue]
      // done
      if ( groupby_dropdown.Date.map(v => v.attribute).indexOf(value) > -1 ) newPData.time_zone_offset =  getTimezoneOffset(dateSegment.tz, new Date() )
      newPData.max_group_number = max_group_number
      newPData.labels = labels
      payloadObj = selectedData === 'none' ? { attribute: 'none', display: 'None', } : newPData
    } else payloadObj = {
        attribute: 'user_custom_property',
        table: 'appuser',
        type: 'json',
        display: eventDisplay,
        json_field: eventDisplay ? [value] : undefined,
        max_group_number,
        labels,
      }
    if (id === 'grp-array' && index >= 0 && index < 2) {
      groupListCopy[index] = payloadObj
      newGroupList = [...groupListCopy]
    }
    if (id === 'grp-main' && groupListCopy.length < 2) newGroupList = [...groupListCopy, payloadObj]
    if (parentType === 'usersAnalytics') await dispatch(setGroupList(newGroupList))
    else await dispatch(
        handleValuesByName({
          dropName: 'group_list',
          data: newGroupList,
        })
      )
    if (
      ['session_period_day'].indexOf(newPData?.attribute) > -1 &&
      series_plot_options?.type === 'pie'
    ) {
      if (parentType === 'usersAnalytics') await dispatch(setSeriesPlotOptions({}))
      else await dispatch(
        handleValuesByName({
          dropName: 'series_plot_options',
          data: {},
        })
      )
    }
    selectedData !== 'session_property' && callGraphApi({ grpList: newGroupList })
    dispatch(
      fetchPlanHatApi({
        action: `Add / change grouping ${index + 1}`,
        info: {
          'Group type': value,
          page: parentType,
        },
      })
    )
  }
  return (
    <div className='stat-full-box'>
      <div className='stat-graph-box'>
        <div className='stat-filter-bar'>
          <div className='filter-left-box'>
            <h4>{!isEmpty(selectedBox) ? selectedBox['graph_info'] : ''}</h4>
            <div className='dropdown-wrapper'>
              <div className='big-combo-box' data-intercom-target="Analytics Group Filter">
                {groupListCopy?.length
                  ? map(groupListCopy, (value, indx) => (
                        <Wrapper
                          label={indx === 0 ? 'Group by' : 'and'}
                          key={value.attribute + indx}
                          _idByArr="grp-array"
                          filterArr={delGrpByArr}
                          _grpByArr={groupListCopy}
                          _index={indx}
                          isRevamped
                        >
                          {groupby_dropdown ? (
                            <CategoryLevelDropdown
                              handleValuesByName={__handleValuesByName}
                              handleChangeEvents={handleGrpBy}
                              key={value.attribute + indx}
                              id='groupby_dropdown'
                              options={groupby_dropdown}
                              eventProperty={false}
                              userProperty
                              eventDropVal={value}
                              _idByArr='grp-array'
                              indexByGrpby={indx}
                              group_list={groupListCopy}
                              isRevamped
                            />
                          ) : (
                            ''
                          )}
                        </Wrapper>
                      ))
                  : null}
              </div>
              {Boolean(groupListCopy?.length === 1) && (
                <Wrapper key='+add-grouping' label="and" isRevamped className='add-btn' dataIntercomTarget="Filter add grouping">
                  {groupby_dropdown ? (
                    <CategoryLevelDropdown
                      handleChangeEvents={handleGrpBy}
                      id='groupby_dropdown'
                      key='+add-grouping'
                      options={groupby_dropdown}
                      eventProperty={false}
                      userProperty
                      _idByArr='grp-main'
                      placeholderText='+ Add grouping'
                      indexByGrpby={1}
                      group_list={groupListCopy}
                      isRevamped
                    />
                  ) : (
                    ''
                  )}
                </Wrapper>
              )}
            </div>
          </div>
          <div className='filter-right-box'>
            <Wrapper dataIntercomTarget="Filter Download">
              <CustomExportGraphDropdown chartRef={chartRef} graphData={graphData} />
            </Wrapper>
            <Wrapper dataIntercomTarget="Filter Graph">
              <GraphTypeDropdown
                handleChartChange={handleChartChange}
                graphTypeVal={graphTypeVal}
                graphTypeObj={graphTypeObj}
                graphData={graphData}
                group_list={groupListCopy}
              />
            </Wrapper>
          </div>
        </div>
        <LoaderAdvanced
          show={!graphData || graphLoader}
          message={insideLoader('Computing chart data')}
          backgroundStyle={{
            backgroundColor: 'rgba(255,255,255,0.6)',
          }}
          style={{
            height: 'calc(100vh - 295px)',
          }}
        >
          <StatisticsGraph
            graphData={graphData}
            height={bottomBarClassFlag ? 'calc(100vh - 350px)' : 'calc(100vh - 345px)'}
            chartRef={chartRef}
            callGraphApi={callGraphApi}
            callStatsBoxes={callStatsBoxes}
          />
        </LoaderAdvanced>
      </div>
    </div>
  )
}
export default memo(Statistics)
