import React, { useState } from 'react'
import { useSelector } from 'react-redux'
import { Select } from 'antd'
import { map } from 'lodash'
import { v4 } from 'uuid'

const { Option, OptGroup } = Select
export const Customary = ({
  handleChange,
  options,
  id,
  placeholder,
  className,
  defaultValue,
  dropdownClassName,
  value,
  style,
  data,
  labelInValue,
  keyVal,
  dropdownStyle,
  grpByToggle,
  toggler,
  _idByArr,
}) => {
  const { dropValues, grpByVal } = useSelector(
    (state) => state.sessionStatisticsReducer
  )
  const [toggle, setToggle] = useState(false)
  return (
    <Select
      placeholder={placeholder}
      className={className}
      defaultValue={defaultValue}
      labelInValue={labelInValue}
      value={value}
      onChange={(val) => handleChange(val)}
      style={style}
      open={_idByArr === 'grp-main' ? grpByToggle : toggle}
      dropdownClassName={dropdownClassName}
      onDropdownVisibleChange={(flag) =>
        _idByArr === 'grp-main' ? '' : setToggle(flag)
      }
      dropdownStyle={dropdownStyle}
      onBlur={() => _idByArr && toggler('grpByToggle', false)}
    >
      {id === 'groupby_dropdown' && (
        <Option key="none" value={id === 'groupby_dropdown' ? 'none' : ''}>
          None
        </Option>
      )}
      {id === 'groupby_dropdown'
        ? map(options, (value, key) => {
            if (key === 'Top') {
              return value
                .filter((x) => x.attribute !== dropValues.attribute)
                .map((x) => (
                  <Option key={v4()} value={x.attribute}>
                    {x.display}
                  </Option>
                ))
            }
              return (
                <OptGroup key={v4()} label={key}>
                  {value
                    .filter(
                      (x) =>
                        x.attribute !== dropValues.attribute &&
                        x.attribute !== 'property'
                    )
                    .map((x) => (
                        <Option key={v4()} value={x.attribute}>
                          {x.display}
                        </Option>
                      ))}
                </OptGroup>
              )

          })
        : map(options, (val, key) => id === 'agg_operators' ? (
              data &&
                data.type === key &&
                map(val, (v, k) => (
                  <Option key={v4()} value={k}>
                    {v.display}
                  </Option>
                ))
            ) : id === 'graph_type_dropdown' ? (
              <Option key={v4()} value={key}>
                <span data-intercom-target="Graph Option">
                <span>{val.img}</span>
                <span className='graph-type-name'>{val.display}</span>
                </span>
              </Option>
            ) : (
              <Option
                disabled={
                  id === 'aggregation' && val[keyVal] === grpByVal.attribute
                }
                key={v4()}
                value={id === 'date_filter_dropdown' ? key : val[keyVal]}
              >
                {id === 'period_groupby_dropdown'
                  ? key
                  : id === 'date_filter_dropdown'
                  ? key
                  : val.display}
              </Option>
            ))}
    </Select>
  )
}
export default Customary
